package com.bank.tf;

import java.util.*;

// Maps config resource addresses -> real cloud resource IDs (the tfstate core).
public class TerraformState {
    private final Map<String,String> resources = new LinkedHashMap<>();
    public void record(String address, String realId) { resources.put(address, realId); }
    public boolean has(String address) { return resources.containsKey(address); }
    public String id(String address) { return resources.get(address); }
    public int size() { return resources.size(); }
    public Map<String,String> all() { return new LinkedHashMap<>(resources); }
}
