package com.bank.tf;

import java.util.*;
import java.util.logging.Logger;

// Versioned, encrypted remote state. Keeps history so a bad write can roll back.
public class S3StateBackend {
    private static final Logger log = Logger.getLogger(S3StateBackend.class.getName());
    private final List<TerraformState> versions = new ArrayList<>();

    public void save(TerraformState s) {
        versions.add(copy(s));
        log.info(() -> "s3: saved state version " + versions.size() + " (encrypted, " + s.size() + " resources)");
    }
    public TerraformState load() {
        return versions.isEmpty() ? new TerraformState() : copy(versions.get(versions.size() - 1));
    }
    public TerraformState rollbackTo(int version) {
        log.warning(() -> "s3: rolling state back to version " + version);
        return copy(versions.get(version - 1));
    }
    private TerraformState copy(TerraformState s) {
        TerraformState c = new TerraformState(); s.all().forEach(c::record); return c;
    }
}
