package com.bank.tf;

import java.util.logging.Logger;

// Serializes applies: a second apply cannot acquire the lock while one holds it.
public class DynamoLock {
    private static final Logger log = Logger.getLogger(DynamoLock.class.getName());
    private String heldBy;

    public synchronized boolean acquire(String who) {
        if (heldBy != null) {
            log.severe(() -> "LOCK HELD by " + heldBy + " — '" + who + "' must WAIT (concurrent apply blocked)");
            return false;
        }
        heldBy = who;
        log.info(() -> "lock acquired by " + who);
        return true;
    }
    public synchronized void release(String who) {
        if (who.equals(heldBy)) { heldBy = null; log.info(() -> "lock released by " + who); }
    }
}
