package com.bank.tf;

import java.util.*;
import java.util.logging.Logger;

// plan: diff desired config vs state; apply: create missing, update state, under lock.
public class ApplyRunner {
    private static final Logger log = Logger.getLogger(ApplyRunner.class.getName());
    private final S3StateBackend backend; private final DynamoLock lock;

    public ApplyRunner(S3StateBackend backend, DynamoLock lock) { this.backend = backend; this.lock = lock; }

    public TerraformState apply(String who, List<String> desired) {
        if (!lock.acquire(who)) return null;             // blocked by concurrent apply
        try {
            TerraformState state = backend.load();
            for (String addr : desired) {
                if (state.has(addr)) {
                    log.info(() -> "plan: " + addr + " exists (" + state.id(addr) + ") — no change");
                } else {
                    String realId = addr.replace('.', '-') + "-" + (state.size() + 1);
                    state.record(addr, realId);
                    log.info(() -> "apply: + create " + addr + " -> " + realId);
                }
            }
            backend.save(state);
            return state;
        } finally {
            lock.release(who);
        }
    }
}
