package com.bank.tf;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TerraformStateDemo {
    private static final Logger log = Logger.getLogger(TerraformStateDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        S3StateBackend backend = new S3StateBackend();
        DynamoLock lock = new DynamoLock();
        ApplyRunner runner = new ApplyRunner(backend, lock);

        List<String> infra = List.of(
                "aws_vpc.bank", "aws_eks_cluster.bank", "aws_db_instance.ledger");

        // First apply provisions infra and records state
        runner.apply("pipeline-run-1", infra);

        // Re-apply from a fresh checkout: state KNOWS resources exist -> no duplicates
        runner.apply("pipeline-run-2", infra);

        // Concurrent apply attempt while lock held is blocked (simulate held lock)
        lock.acquire("long-running-apply");
        runner.apply("racing-apply", infra);   // blocked
        lock.release("long-running-apply");

        // Provisioned ledger DB now backs a real transfer
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on ledger DB provisioned by Terraform");
    }
}
